#include "protocol.h"
#include "authentication.h"
#include <stdio.h>
#include <string.h>
int protocol_accept_identity(network_socket socket,const contact_book*book,contact_role role,const contact**identity){char nonce[33],line[COUNCIL_MESSAGE_LENGTH],name[COUNCIL_NAME_LENGTH],given[65],wanted[65];const contact*person;authentication_nonce(nonce);snprintf(line,sizeof(line),"NONCE %s\n",nonce);if(network_send(socket,line)||network_read_line(socket,line,sizeof(line))<0||sscanf(line,"AUTH %63s %64s",name,given)!=2)return -1;person=contact_book_find(book,name);if(!person||person->role!=role){network_send(socket,"ERROR IDENTITY\n");return -1;}authentication_digest(person->shared_key,name,nonce,wanted);if(!authentication_matches(given,wanted)){network_send(socket,"ERROR AUTHENTICATION\n");return -1;}if(network_send(socket,"OK\n"))return -1;*identity=person;return 0;}
int protocol_connect_identity(const contact*d,const char*local_name,network_socket*s){char line[COUNCIL_MESSAGE_LENGTH],digest[65];if(network_connect(d->host,d->port,s))return -1;if(network_read_line(*s,line,sizeof(line))<0||strncmp(line,"NONCE ",6)){network_close(*s);return -1;}authentication_digest(d->shared_key,local_name,line+6,digest);snprintf(line,sizeof(line),"AUTH %s %s\n",local_name,digest);if(network_send(*s,line)||network_read_line(*s,line,sizeof(line))<0||strcmp(line,"OK")){network_close(*s);return -1;}return 0;}
int protocol_send_command(const contact*d,const char*local_name,const char*command,char*reply,size_t reply_size){network_socket s;char line[COUNCIL_MESSAGE_LENGTH];if(strchr(command,'\n')||strchr(command,'\r'))return -1;if(protocol_connect_identity(d,local_name,&s))return -1;snprintf(line,sizeof(line),"%s\n",command);if(network_send(s,line)||network_read_line(s,reply,reply_size)<0){network_close(s);return -1;}network_close(s);return 0;}
